    def put(self, queue, message, **kwargs):
        """Put `message` onto `queue`.

        Applies the queue's message TTL (when the message does not carry
        its own expiration) and enforces the queue's maximum length,
        dead lettering any evicted messages with reason ``"maxlen"``.
        """
        message = self._apply_queue_ttl(queue, message)
        self._enforce_max_length(queue, message)
        return self._put(queue, message, **kwargs)

    def _put_fanout(self, exchange, message, routing_key=None, **kwargs):
        """Put `message` on every queue bound to `exchange`."""
        for queue in self._lookup(exchange, routing_key):
            self.put(queue, message, **kwargs)

    def _apply_queue_ttl(self, queue, message):
        """Return `message` stamped with an ``x-expires-at`` timestamp.

        A per-message ``expiration`` takes precedence over the queue's
        ``x-message-ttl``.  Whenever a timestamp is stamped, an
        independent copy of the message is returned, so that messages
        delivered to several queues with different TTLs get independent
        expiry timestamps.
        """
        properties = message['properties']
        if properties.get('x-expires-at') is not None:
            return message
        expires_at = self._expiration_to_expires_at(
            properties.get('expiration'))
        if expires_at is None:
            ttl_ms = self.get_queue_properties(queue).get('message_ttl')
            if ttl_ms is None:
                return message
            expires_at = monotonic() + float(ttl_ms) / 1000.0
        message = self._copy_message(message)
        message['properties']['x-expires-at'] = expires_at
        return message

    def _expiration_to_expires_at(self, expiration):
        """Convert a per-message `expiration` (ms) to an absolute time."""
        if expiration is None:
            return None
        try:
            expiration_ms = float(expiration)
        except (TypeError, ValueError):
            return None
        return monotonic() + expiration_ms / 1000.0

    def _enforce_max_length(self, queue, message):
        """Evict the oldest messages so the queue fits its max length.

        The evicted messages are dead-lettered with reason ``"maxlen"``.
        """
        max_length = self.get_queue_properties(queue).get('max_length')
        if not max_length:
            return
        overflow = self._size(queue) + 1 - int(max_length)
        for _ in range(max(0, overflow)):
            try:
                evicted = self._get(queue)
            except Empty:
                break
            self.dead_letter(evicted, queue, 'maxlen')

    def _copy_message(self, message):
        """Return an independent deep copy of the raw `message`."""
        return copy.deepcopy(message)

    def message_ttl_remaining(self, message):
        """Return the seconds remaining before `message` expires.

        Returns :const:`None` if the message carries no
        ``x-expires-at`` timestamp, or a negative value if the message
        has already expired.
        """
        if isinstance(message, dict):
            properties = message.get('properties') or {}
        else:
            properties = message.properties or {}
        expires_at = properties.get('x-expires-at')
        if expires_at is None:
            return None
        return expires_at - monotonic()

    def _is_expired(self, message):
        """Return true if `message` has passed its expiry time."""
        remaining = self.message_ttl_remaining(message)
        return remaining is not None and remaining <= 0

    def drain_expired(self, queue):
        """Remove expired messages from `queue`, dead lettering them.

        Surviving messages are left intact, and the number of expired
        messages removed is returned.
        """
        messages = []
        while True:
            try:
                messages.append(self._get(queue))
            except Empty:
                break
        expired = []
        survivors = []
        for message in messages:
            (expired if self._is_expired(message) else survivors).append(
                message)
        for message in expired:
            self.dead_letter(message, queue, 'expired')
        for message in survivors:
            self._put(queue, message)
        return len(expired)
